284	
285	  describe('full lifecycle order', () => {
286	    it('calls all hooks in correct order', async () => {
287	      const callOrder: string[] = [];
288	      const usage: UsageMetadata = {inputTokens: 5, outputTokens: 3, totalTokens: 8};
289	
290	      const hooks: OrchestratorHooks = {
291	        beforeSession: async () => {
292	          callOrder.push('beforeSession');
293	        },
294	        beforeUserInput: async (_s, msg) => {
295	          callOrder.push('beforeUserInput');
