338	
339	      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('fail')), promptBuilder, undefined, {
340	        hooks,
341	      });
342	      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));
343	
344	      expect({outcome, callOrder}).toEqual({
345	        outcome: 'fail',
346	        callOrder: [
347	          'beforeSession',
348	          'beforeUserInput',
349	          'afterUserInput',
350	          'beforeModelResponse',
351	          'onError',
352	          'afterSession',
353	        ],
