367	// One scripted round per sendMessage call, to drive the tool loop round by round.
368	const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
369	  let round = 0;
370	
371	  return {
372	    async *sendMessage(): AsyncGenerator<MessageChunk> {
373	      for (const chunk of rounds[round++] ?? []) yield chunk;
374	    },
375	    async generateStructured<T>(): Promise<T> {
376	      return {} as T;
377	    },
378	  };
379	};
380	
381	const registryReturning = (response: ToolResponse): ToolRegistry => {
382	  const registry = new ToolRegistry();
383	  registry.register(
384	    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
385	    async () => response
386	  );
387	  return registry;
388	};
389	
390	const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
391	const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
392	const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
393	
394	const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
395	  const chunks: MessageChunk[] = [];
396	  for await (const chunk of stream) chunks.push(chunk);
397	  return chunks;
398	};
399	
400	describe('ChatOrchestrator tool loop', () => {
401	  it('runs another round after a tool call and streams both rounds in order', async () => {
402	    const provider = scriptedProvider([
403	      [TOOL_CALL, STOP_FOR_TOOL],
404	      [{type: 'text', text: 'the answer'}, STOP_DONE],
405	    ]);
406	    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));
407	
408	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
409	
410	    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
411	  });
412	
413	  it('stops after one round when nothing asked for a tool', async () => {
414	    const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
415	    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'x'}));
416	
417	    const text = await orchestrator.processMessage(createSession('ask'));
418	
419	    expect(text).toBe('done');
420	  });
421	
422	  it('stops asking for tools once maxToolRounds is spent', async () => {
423	    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
424	    const orchestrator = createChatOrchestrator(
425	      scriptedProvider(alwaysTools),
426	      promptBuilder,
427	      registryReturning({result: 'again'}),
428	      {maxToolRounds: 2}
429	    );
430	
431	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
432	
433	    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(3);
434	  });
435	
436	  it('forwards the client messages a tool returned as one tool_result chunk', async () => {
437	    const forwarded: OutgoingMessage = {type: 'entry_commit', index: 7};
438	    const orchestrator = createChatOrchestrator(
439	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
440	      promptBuilder,
441	      registryReturning({result: 'r', clientMessages: [forwarded]})
442	    );
443	
444	    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));
445	
446	    expect(chunks).toContainEqual({type: 'tool_result', clientMessages: [forwarded]});
447	  });
448	
449	  it('appends an upserted entry to the session and rewrites its index to match', async () => {
450	    const entry: SessionEntry = {role: 'assistant', content: 'from the tool', timestamp: SENT_AT, isStreaming: false};
451	    const orchestrator = createChatOrchestrator(
452	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
453	      promptBuilder,
454	      registryReturning({result: 'r', clientMessages: [{type: 'entry_upsert', index: 999, entry}]})
455	    );
456	    const session = createSession('ask');
457	
458	    const chunks = await chunksFrom(orchestrator.processMessageStream(session));
459	
460	    expect(chunks).toContainEqual({
461	      type: 'tool_result',
462	      clientMessages: [{type: 'entry_upsert', index: session.entries.length - 1, entry}],
463	    });
464	  });
465	
466	  it('asks for suppression when the tool says the reply is already handled', async () => {
467	    const orchestrator = createChatOrchestrator(
468	      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
469	      promptBuilder,
470	      registryReturning({result: 'r', suppressAssistantResponse: true})
